  "review_title": "Max Coolant Pressure Conflict in THERMAL-HVAC",
  "overall_status": "blocking",
  "executive_summary": "Proposed update to Max Coolant Pressure (3.94 bar) conflicts with certified specification in DOC-HVAC-301 (3.5 bar).",
  "findings": [
    {
      "finding_id": "FIND-NUM-001",
      "category": "policy_conflict",
      "severity": "medium",
      "title": "Max Coolant Pressure Exceeds Certified Threshold",
      "description": "Proposed value 3.94 bar exceeds certified 3.5 bar (+12.5% drift).",
      "evidence": [
        {
          "source": "DOC-HVAC-301",
          "quote": "Primary refrigerant loop pressure must not exceed 3.5 bar under dynamic cooling load. Chiller delivery temperature must ",
          "location": "Section 1"
        }
      ],
      "impact": "Breaching 3.5 bar introduces hardware overstress or operational policy failure.",
      "recommended_fix": "Maintain certified ceiling 3.5 bar or submit formal engineering sign-off.",
      "confidence": "high",
      "is_inference": false,
      "needs_human_verification": true
    }
  ],
  "missing_information": [],
  "improvements": [
    {
      "title": "Re-clamp Max Coolant Pressure",
      "description": "Restore parameter to <= 3.5 bar.",
      "linked_finding_ids": [
        "FIND-NUM-001"
      ],
      "type": "required_fix"
    }
  ],
  "assumptions": [],
  "questions_for_reviewer": [
    "Has the engineering team bench-tested 3.94 bar under peak ambient stress?"
