{
  "schema_version": "1.0",
  "review_title": "Specification Conflict in TRACTION-MOTOR",
  "overall_status": "blocking",
  "executive_summary": "Supplied documents contain conflicting tolerances. Unified 19200.0 rpm violates primary standard in DOC-MOTOR-800.",
  "findings": [
    {
      "finding_id": "FIND-CONF-001",
      "category": "policy_conflict",
      "severity": "high",
      "title": "Specification Contradiction Between DOC-MOTOR-800 and DOC-MOTOR-800-EXT",
      "description": "DOC-MOTOR-800-EXT allows 19200.0 rpm, but DOC-MOTOR-800 strictly caps parameter at 16000.0 rpm.",
      "evidence": [
        {
          "source": "DOC-MOTOR-800",
          "quote": "Continuous operational motor speed ceiling is 16000 rpm. Stator winding temperature cannot",
          "location": "Certified Base"
        },
        {
          "source": "DOC-MOTOR-800-EXT",
          "quote": "Auxiliary systems permit excursions up to 19200.0 rpm for brief intervals.",
          "location": "Extension Clause"
        }
      ],
      "impact": "Applying unified value introduces component failure in baseline modules.",
      "recommended_fix": "Preserve module-specific limits: 16000.0 rpm for primary, 19200.0 rpm for auxiliary.",
      "confidence": "high",
      "is_inference": false,
      "needs_human_verification": true
    }
  ],
  "missing_information": [],
  "improvements": [
    {
      "title": "Decouple Module Standards",
      "description": "Maintain separate configuration keys per subsystem.",
      "linked_finding_ids": [
        "FIND-CONF-001"
      ],
      "type": "required_fix"
    }
  ],
